  // kept below the nebula's own radiance so it reads as glare, not as fog.
  col += uSunColour * (0.85 * exp(-ang / 0.009)
                     + 0.15 * exp(-ang / 0.050)
                     + 0.016 * exp(-ang / 0.320));

